package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.annotation.JsonCreator;
import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.annotation.JsonInclude;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.core.Version;
import com.fasterxml.jackson.core.Versioned;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.JsonSerializer;
import com.fasterxml.jackson.databind.annotation.JsonPOJOBuilder;
import com.fasterxml.jackson.databind.annotation.JsonSerialize;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.deser.ValueInstantiator;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.introspect.Annotated;
import com.fasterxml.jackson.databind.introspect.AnnotatedClass;
import com.fasterxml.jackson.databind.introspect.AnnotatedMember;
import com.fasterxml.jackson.databind.jsontype.NamedType;
import com.fasterxml.jackson.databind.jsontype.TypeResolverBuilder;
import com.fasterxml.jackson.databind.ser.BeanPropertyWriter;
import com.fasterxml.jackson.databind.type.MapLikeType;
import com.fasterxml.jackson.databind.type.MapType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.type.array.ArrayType;
import com.fasterxml.jackson.databind.util.Converter;
import com.fasterxml.jackson.databind.util.NameTransformer;
import java.io.*;
import java.lang.annotation.Annotation;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class AnnotationIntrospector_refineDeserializationType_TriageGen2Test {

    private AnnotationIntrospector introspector;
    private MapperConfig<?> config;
    private TypeFactory typeFactory;
    private Annotated annotated;

    @Before
    public void setUp() {
        // We need a concrete implementation of AnnotationIntrospector to test the logic 
        // because the method is abstract in the base class but implemented in subclasses 
        // or used via a spy for the purpose of this unit test logic.
        // However, since the method provided in the prompt is the implementation logic 
        // itself, we will use a Spy on a dummy implementation.
        introspector = spy(new AnnotationIntrospector.Base());
        config = mock(MapperConfig.class);
        typeFactory = TypeFactory.defaultInstance();
        when(config.getTypeFactory()).thenReturn(typeFactory);
        annotated = mock(Annotated.class);
        when(annotated.getName()).thenReturn("testAnnotation");
    }

    /**
     * Test Case 1: No refinement needed.
     * The find methods return null, so the baseType should be returned as is.
     */
    @Test
    public void testRefineDeserializationType_NoChange() throws JsonMappingException {
        JavaType baseType = typeFactory.constructType(Object.class);

        doReturn(null).when(introspector).findDeserializationType(any(), any());
        doReturn(null).when(introspector).findDeserializationKeyType(any(), any());
        doReturn(null).when(introspector).findDeserializationContentType(any(), any());

        JavaType result = introspector.refineDeserializationType(config, annotated, baseType);

        assertSame(baseType, result);
    }

    /**
     * Test Case 2: Refine the main type.
     * findDeserializationType returns a specific class.
     */
    @Test
    public void testRefineDeserializationType_RefineMainType() throws JsonMappingException {
        JavaType baseType = typeFactory.constructType(Object.class);
        Class<?> targetClass = String.class;

        doReturn(targetClass).when(introspector).findDeserializationType(annotated, baseType);
        doReturn(null).when(introspector).findDeserializationKeyType(any(), any());
        doReturn(null).when(introspector).findDeserializationContentType(any(), any());

        JavaType result = introspector.refineDeserializationType(config, annotated, baseType);

        assertEquals(targetClass, result.getRawClass());
    }

    /**
     * Test Case 3: Refine Map Key type.
     * The type is Map-like, and findDeserializationKeyType returns a class.
     */
    @Test
    public void testRefineDeserializationType_RefineKeyType() throws JsonMappingException {
        // Map<Object, Object>
        JavaType baseType = typeFactory.constructMapType(HashMap.class, Object.class, Object.class);
        Class<?> keyClass = Integer.class;

        doReturn(null).when(introspector).findDeserializationType(any(), any());
        doReturn(keyClass).when(introspector).findDeserializationKeyType(annotated, any(JavaType.class));
        doReturn(null).when(introspector).findDeserializationContentType(any(), any());

        JavaType result = introspector.refineDeserializationType(config, annotated, baseType);

        assertEquals(keyClass, result.getKeyType().getRawClass());
        // Ensure it's still a Map type
        assertTrue(result.isMapLikeType());
    }

    /**
     * Test Case 4: Refine Content type (List/Array).
     * findDeserializationContentType returns a class.
     */
    @Test
    public void testRefineDeserializationType_RefineContentType() throws JsonMappingException {
        // List<Object>
        JavaType baseType = typeFactory.constructCollectionType(java.util.List.class, Object.class);
        Class<?> contentClass = String.class;

        doReturn(null).when(introspector).findDeserializationType(any(), any());
        doReturn(null).when(introspector).findDeserializationKeyType(any(), any());
        doReturn(contentClass).when(introspector).findDeserializationContentType(annotated, any(JavaType.class));

        JavaType result = introspector.refineDeserializationType(config, annotated, baseType);

        assertEquals(contentClass, result.getContentType().getRawClass());
    }

    /**
     * Test Case 5: Refine both Key and Content (Map<Object, Object> -> Map<Integer, String>).
     */
    @Test
    public void testRefineDeserializationType_RefineKeyAndContent() throws JsonMappingException {
        JavaType baseType = typeFactory.constructMapType(HashMap.class, Object.class, Object.class);
        Class<?> keyClass = Integer.class;
        Class<?> contentClass = String.class;

        doReturn(null).when(introspector).findDeserializationType(any(), any());
        doReturn(keyClass).when(introspector).findDeserializationKeyType(annotated, any(JavaType.class));
        doReturn(contentClass).when(introspector).findDeserializationContentType(annotated, any(JavaType.class));

        JavaType result = introspector.refineDeserializationType(config, annotated, baseType);

        assertEquals(keyClass, result.getKeyType().getRawClass());
        assertEquals(contentClass, result.getContentType().getRawClass());
    }

    /**
     * Test Case 6: Exception handling for main type refinement.
     * Triggered if tf.constructSpecializedType throws IllegalArgumentException.
     * Since we can't easily force tf.constructSpecializedType to fail with the default instance 
     * without complex mocking, we simulate the logic flow.
     */
    @Test(expected = JsonMappingException.class)
    public void testRefineDeserializationType_ThrowExceptionOnMainType() throws JsonMappingException {
        // To trigger the catch block, we need to cause constructSpecializedType to throw.
        // We can mock the TypeFactory to throw an exception.
        TypeFactory mockTf = mock(TypeFactory.class);
        when(config.getTypeFactory()).thenReturn(mockTf);

        JavaType baseType = typeFactory.constructType(Object.class);
        Class<?> targetClass = String.class;

        doReturn(targetClass).when(introspector).findDeserializationType(any(), any());
        when(mockTf.constructSpecializedType(any(), any())).thenThrow(new IllegalArgumentException("Mock error"));

        introspector.refineDeserializationType(config, annotated, baseType);
    }

    /**
     * Test Case 7: Exception handling for Key type refinement.
     */
    @Test(expected = JsonMappingException.class)
    public void testRefineDeserializationType_ThrowExceptionOnKeyType() throws JsonMappingException {
        TypeFactory mockTf = mock(TypeFactory.class);
        when(config.getTypeFactory()).thenReturn(mockTf);

        JavaType baseType = typeFactory.constructMapType(HashMap.class, Object.class, Object.class);
        Class<?> keyClass = Integer.class;

        doReturn(null).when(introspector).findDeserializationType(any(), any());
        doReturn(keyClass).when(introspector).findDeserializationKeyType(any(), any());

        // When attempting to construct specialized key type, throw exception
        when(mockTf.constructSpecializedType(any(), eq(keyClass))).thenThrow(new IllegalArgumentException("Key error"));

        introspector.refineDeserializationType(config, annotated, baseType);
    }

    /**
     * Test Case 8: Exception handling for Content type refinement.
     */
    @Test(expected = JsonMappingException.class)
    public void testRefineDeserializationType_ThrowExceptionOnContentType() throws JsonMappingException {
        TypeFactory mockTf = mock(TypeFactory.class);
        when(config.getTypeFactory()).thenReturn(mockTf);

        JavaType baseType = typeFactory.constructArrayType(Object.class);
        Class<?> contentClass = String.class;

        doReturn(null).when(introspector).findDeserializationType(any(), any());
        doReturn(null).when(introspector).findDeserializationKeyType(any(), any());
        doReturn(contentClass).when(introspector).findDeserializationContentType(any(), any());

        // When attempting to construct specialized content type, throw exception
        when(mockTf.constructSpecializedType(any(), eq(contentClass))).thenThrow(new IllegalArgumentException("Content error"));

        introspector.refineDeserializationType(config, annotated, baseType);
    }
}
